"""
    = Expected Configuration Sections And Parameter Names =
    "rf_module":{
        "bts_config_name":"bts",
        "user": "",
        "password": "",
        "lxc_command":"",
        "fhnet_prompt":"",
        "rfmod_prompt": ""
        }
"""
from taf.ul.trs_e2e_fw.lib.utils.front_haul_modules.rf_module.rf_module import RfModule


def rfmodule_setup(**kwargs):
    """
    Login to RF module

    *Usage*:
        Rfmodule Setup <config_device> <rfmod_inst_id> <fhnet_login_only> <iprange> <alias>
        <timeout>

    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | config_device | 'bts' | Name of the section in testline config  | `testline_config` |
    | rfmod_inst_id | '1' | RF module inst ID |  |
    | rf_ip_distname | /MRBTS-1/RAT-1/BTS_L-1/EQM_L-1/RMOD_L-rfmod_inst_id:ipAddress | RF module dist name |  |
    | fhnet_login_only | False | Skips RF module login, if set to True |  |
    | iprange | None | ip range |  |
    | alias | 'default' | Name of execution context |  |
    | timeout | 10 | Timeout for connection in seconds |  |

    *Example*
    | *keyword* | *device* | *command_profile* |
    | *Rfmodule Setup* | config_device='rfmodule' | alias='rf_session1' |

    *Returns* \n
    This keyword returns nothing. By default None will be returned.

    *Possible Exceptions* \n
    FHNetLoginFailedException, RFModuleLoginFailedException
    """
    RfModule().rfmodule_setup(**kwargs)


def rfmodule_teardown(**kwargs):
    """
    Teardown RF module connection

    *Usage*:
        Rfmodule Teardown <alias>


    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | alias | 'default' | Name of execution context |  |

    *Example*
    | *keyword* | *device* | *command_profile* |
    | *Rfmodule Teardown* | alias='rf_session1' |

    *Returns* \n
    This keyword returns nothing. By default None will be returned.

    *Possible Exceptions* \n
    SSHException : If established SSH connection is not available to close.
    """
    RfModule().rfmodule_teardown(**kwargs)
